	git_vector     *stack,
	const char     *base,
	const char     *filename,
	int (*loader)(git_repository *, const char *, git_attr_file **))
{
	int error = GIT_SUCCESS;
	git_attr_cache *cache = &repo->attrcache;
	git_buf path = GIT_BUF_INIT;
	git_attr_file *file;
	int add_to_cache = 0;

	if (base != NULL) {
		if ((error = git_buf_joinpath(&path, base, filename)) < GIT_SUCCESS)
			goto cleanup;
		filename = path.ptr;
